/*updateCommonMpIvDetailInvoiceCreationPop*/
	UPDATE EDIVPODT SET
	    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
	    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
	    IV_QTY	=	NVL(#{iv_qty}, 0),
	    VIV_DATE	=	#{rd_date},
	    RECV_FLAG = 'B'
	WHERE  BUYER		=	#{st_buyer}
	    AND  VPO_NO	=	#{st_vpo_no}
	    AND  VPO_SEQ	=	#{vpo_seq}
